import RPi.GPIO as GPIO
import spidev
import time
import logging
import argparse
import threading
import queue
import sys

# Define a class for the sound sensor
class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed, log_queue):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.running = True
        self.spi = None
        self.gpio_pins = [int(pin) for pin in gpio_pins.split(",")] if gpio_pins else None
        self.channels = [int(chan) for chan in channels.split(",")] if channels else None

        # Validate sensor type
        if self.sensor_type not in ["digital", "analog"]:
            raise ValueError("Invalid sensor type. Must be 'digital' or 'analog'.")

        # Validate sensor ID
        if not isinstance(sensor_id, int):
            raise ValueError("Sensor ID must be an integer.")

        # Validate threshold
        if not isinstance(threshold, int):
            raise ValueError("Threshold must be an integer.")

        # Validate sample rate
        if not isinstance(sample_rate, int) or sample_rate <= 0:
            raise ValueError("Sample rate must be a positive integer.")

        # Validate GPIO pins
        if self.gpio_pins:
            if len(self.gpio_pins) != 1:
                raise ValueError("Exactly one GPIO pin must be specified for digital sensors.")
            for pin in self.gpio_pins:
                if not isinstance(pin, int):
                    raise ValueError("GPIO pin must be an integer.")

        # Validate channels
        if self.channels:
            if len(self.channels) != 1:
                raise ValueError("Exactly one channel must be specified for analog sensors.")
            for channel in self.channels:
                if not isinstance(channel, int):
                    raise ValueError("Channel must be an integer.")

        # Initialize GPIO if using digital sensor
        if self.gpio_pins:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.gpio_pins[0], GPIO.IN, pull_up_down=GPIO.PUD_DOWN)

        # Initialize SPI if using analog sensor
        if self.channels:
            try:
                self.spi = spidev.SpiDev()
                self.spi.open(0, 0)  # Bus 0, Device 0
                self.spi.max_speed_hz = self.spi_speed
            except Exception as e:
                logging.error(f"Error initializing SPI: {e}")
                self.spi = None

    def read_digital_sensor(self):
        """Reads the digital sound sensor."""
        try:
            return GPIO.input(self.gpio_pins[0])
        except Exception as e:
            logging.error(f"Error reading digital sensor {self.sensor_id}: {e}")
            return None

    def read_analog_sensor(self):
        """Reads the analog sound sensor via MCP3008."""
        if not self.spi:
            logging.error(f"SPI not initialized for sensor {self.sensor_id}.")
            return None

        try:
            # MCP3008 single-ended read
            adc_channel = self.channels[0]
            r = self.spi.xfer2([1, (8 + adc_channel) << 4, 0])
            adc_out = ((r[1] & 3) << 8) + r[2]
            return adc_out
        except Exception as e:
            logging.error(f"Error reading analog sensor {self.sensor_id}: {e}")
            return None

    def detect_sound(self):
        """Detects sound based on sensor type and threshold."""
        if self.sensor_type == "digital":
            reading = self.read_digital_sensor()
            if reading is not None:
                return reading == 1
        elif self.sensor_type == "analog":
            reading = self.read_analog_sensor()
            if reading is not None:
                return reading >= self.threshold
        return False

    def run(self):
        """Runs the sound detection loop."""
        while self.running:
            if self.detect_sound():
                timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
                message = f"Sensor {self.sensor_id}: Sound detected at {timestamp}"
                self.log_queue.put(message)
                time.sleep(0.1)  # Debounce
            time.sleep(1 / self.sample_rate)

    def stop(self):
        """Stops the sound detection loop."""
        self.running = False

    def cleanup(self):
        """Cleans up GPIO resources."""
        if self.gpio_pins:
            GPIO.cleanup(self.gpio_pins)
        if self.spi:
            self.spi.close()

def log_messages(log_queue, log_file):
    """Logs messages from the queue to a file."""
    try:
        with open(log_file, "a") as f:
            while True:
                try:
                    message = log_queue.get(timeout=1)  # Wait for 1 second
                    f.write(message + "\n")
                    f.flush()  # Ensure message is written immediately
                    log_queue.task_done()
                except queue.Empty:
                    break  # Check queue every second
    except Exception as e:
        logging.error(f"Error writing to log file: {e}")

def main():
    """Main function to parse arguments and start the sound detection threads."""
    parser = argparse.ArgumentParser(description="Sound detection system for Raspberry Pi.")
    parser.add_argument("--sensor_type", required=True, help="Sensor type (digital or analog).")
    parser.add_argument("--threshold", type=int, required=True, help="Sound detection threshold (0-1023 for analog, 0 or 1 for digital).")
    parser.add_argument("--sample_rate", type=int, default=10, help="Sampling rate in Hz (1-100).")
    parser.add_argument("--log_file", required=True, help="Path to the log file.")
    parser.add_argument("--gpio_pins", help="GPIO pin numbers for digital sensors (comma-separated).")
    parser.add_argument("--channels", help="MCP3008 channel numbers for analog sensors (comma-separated).")
    parser.add_argument("--spi_speed", type=int, default=1000000, help="SPI speed in Hz.")
    parser.add_argument("--sensor_ids", required=True, help="Comma-separated list of sensor IDs.")

    args = parser.parse_args()

    # Configure logging
    logging.basicConfig(filename=args.log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

    # Parse sensor IDs
    sensor_ids = [int(sensor_id) for sensor_id in args.sensor_ids.split(",")]

    # Create a queue for logging messages
    log_queue = queue.Queue()

    # Create and start threads for each sensor
    threads = []
    sensors = []
    try:
        for sensor_id in sensor_ids:
            try:
                sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate,
                                     args.gpio_pins, args.channels, args.spi_speed, log_queue)
                sensors.append(sensor)
                thread = threading.Thread(target=sensor.run)
                threads.append(thread)
                thread.daemon = True  # Allow main thread to exit even if this thread is running
                thread.start()
            except ValueError as e:
                logging.error(f"Error creating sensor {sensor_id}: {e}")
            except Exception as e:
                logging.error(f"Unexpected error creating sensor {sensor_id}: {e}")

        # Start the logging thread
        logging_thread = threading.Thread(target=log_messages, args=(log_queue, args.log_file))
        logging_thread.daemon = True
        logging_thread.start()

        # Keep the main thread alive until a KeyboardInterrupt occurs
        while True:
            time.sleep(1)

    except KeyboardInterrupt:
        print("Shutting down...")
        logging.info("Shutting down...")
    finally:
        # Stop all sensors
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()  # Wait for all threads to finish

        # Clean up GPIO resources
        for sensor in sensors:
            sensor.cleanup()

        # Close the log file
        logging.shutdown()

if __name__ == "__main__":
    main()

