# Import necessary libraries
import cv2
from pyzbar.pyzbar import decode
from PIL import Image
import numpy as np

def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        cap = cv2.VideoCapture(0)
        if not cap.isOpened():
            raise Exception("Failed to open camera")
        return cap
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_frame(cap):
    """Captures a single frame from the camera."""
    try:
        ret, frame = cap.read()
        if not ret:
            raise Exception("Failed to capture frame")
        return frame
    except Exception as e:
        print(f"Error capturing frame: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes in a frame."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = decode(gray)
        return decoded_objects
    except Exception as e:
        print(f"Error decoding QR code: {e}")
        return None

def process_qr_code(decoded_objects):
    """Processes decoded QR code data."""
    if decoded_objects:
        for obj in decoded_objects:
            data = obj.data.decode('utf-8')
            print(f"QR code data: {data}")
            return data
    return None

def release_resources(cap):
    """Releases camera resources."""
    if cap:
        cap.release()

def main():
    """Main function to capture and decode QR code."""
    cap = initialize_camera()

    if cap is None:
        print("Exiting due to camera initialization failure.")
        return

    try:
        frame = capture_frame(cap)
        if frame is None:
            print("Exiting due to frame capture failure.")
            return

        decoded_objects = decode_qr_code(frame)

        if decoded_objects:
            qr_data = process_qr_code(decoded_objects)
            if qr_data:
                print("Hello, World!")
        else:
            print("No QR code detected.")

    except Exception as e:
        print(f"An unexpected error occurred: {e}")

    finally:
        release_resources(cap)
        print("Camera resources released.")

if __name__ == "__main__":
    main()

