import cv2,sys,hardware,config,face
import time
import logging

logging.basicConfig(level=logging.INFO)
logger=logging.getLogger(__name__)

b=hardware.Box()
b.lock()
c=cv2.face.EigenFaceRecognizer_create()
c.read(config.TRAINING_FILE)
w=cv2.VideoCapture(0,cv2.CAP_V4L2)
if not w.isOpened():
    raise IOError("Cannot open camera")
w.set(cv2.CAP_PROP_FRAME_WIDTH,64)
w.set(cv2.CAP_PROP_FRAME_HEIGHT,48)


def detect(i):
    m=cv2.cvtColor(i,cv2.COLOR_BGR2GRAY)
    f=cv2.CascadeClassifier(config.HAAR_FILE)
    r=f.detectMultiScale(m,1.3,5)
    if r:return m,r

def crop(i,x,y,w,h):
    return i[y:y+h,x:x+w]

def resize(i,s):
    return cv2.resize(i,(s,s))

def main():
    logger.info("Running")
    while True:
        if b.is_button_up():
            if b.is_locked:
                logger.info("Button up, looking for face")
                i=w.read()[1]
                if not i is None:
                    m,r=detect(i)
                    if r:
                        x,y,w,h=r[0]
                        i=crop(i,x,y,w,h)
                        i=resize(i,10)
                        l,conf=c.predict(i)
                        logger.info("Prediction %s (%.2f)",l,conf)
                        if l==config.POSITIVE_LABEL and config.POSITIVE_THRESHOLD>conf>1500:
                            b.unlock()
                            logger.info("Unlocked")
        time.sleep(0.1)

if __name__=="__main__":
    try:
        main()
    except KeyboardInterrupt:
        logger.info("Exiting")
    finally:
        w.release()
        b.lock()

