# QR Code Inventory System for Raspberry Pi
# Author: Bard
# Date: October 26, 2023
# This program captures QR codes from a USB camera, logs the data to a CSV file, and handles errors gracefully.

import cv2
from pyzbar.pyzbar import decode
from PIL import Image
import csv
import datetime
import time
import os

# Configuration
CAMERA_INDEX = 0  # Index of the USB camera
LOG_FILE = "inventory_log.csv"
ERROR_LOG = "error_log.txt"

def initialize_camera():
    """Initializes the camera and returns the capture object."""
    try:
        cap = cv2.VideoCapture(CAMERA_INDEX)
        if not cap.isOpened():
            raise Exception("Could not open camera")
        return cap
    except Exception as e:
        log_error(f"Camera initialization error: {e}")
        return None

def capture_frame(cap):
    """Captures a frame from the camera."""
    try:
        ret, frame = cap.read()
        if not ret:
            raise Exception("Failed to capture frame")
        return frame
    except Exception as e:
        log_error(f"Frame capture error: {e}")
        return None

def decode_qr_code(frame):
    """Decodes QR codes in a frame."""
    try:
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
        decoded_objects = decode(gray)
        return decoded_objects
    except Exception as e:
        log_error(f"QR code decoding error: {e}")
        return None

def validate_data(data):
    """Validates the decoded data."""
    try:
        if not data:
            return False
        if not all(char.isalnum() for char in data):
            return False
        return True
    except Exception as e:
        log_error(f"Data validation error: {e}")
        return False

def log_data(item_id):
    """Logs the data to the CSV file."""
    try:
        timestamp = datetime.datetime.now().isoformat()
        with open(LOG_FILE, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            # Check if the file is empty to write the header
            if os.stat(LOG_FILE).st_size == 0:
                writer.writerow(["Camera", "Item ID", "Timestamp"])
            writer.writerow(["Camera 1", item_id, timestamp])
    except Exception as e:
        log_error(f"Data logging error: {e}")

def log_error(message):
    """Logs an error message to the error log file."""
    try:
        timestamp = datetime.datetime.now().isoformat()
        with open(ERROR_LOG, 'a') as f:
            f.write(f"{timestamp} - {message}\n")
    except Exception as e:
        print(f"Error logging error: {e}") # Print to console if error log fails

def main():
    """Main function to run the QR code inventory system."""
    cap = initialize_camera()
    if cap is None:
        print("Camera initialization failed. Exiting.")
        return

    try:
        while True:
            frame = capture_frame(cap)
            if frame is None:
                continue

            decoded_objects = decode_qr_code(frame)
            if decoded_objects is None:
                continue

            for obj in decoded_objects:
                data = obj.data.decode("utf-8")
                if validate_data(data):
                    log_data(data)
                    print(f"Item ID: {data} logged.")

            time.sleep(0.2)  # Reduced delay for faster scanning

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        log_error(f"An unexpected error occurred: {e}")
    finally:
        # Release the camera and close all windows
        cap.release()
        cv2.destroyAllWindows()
        print("Camera released and windows closed.")

if __name__ == "__main__":
    main()

