import os
import time
import signal
import threading
from typing import List, Tuple

try:
    from PIL import Image, ImageOps
except ImportError:
    print("PIL (Pillow) is required. Please install it using: pip install Pillow")
    exit(1)

try:
    import RPi.GPIO as GPIO
    from lib_st7789 import ST7789
except ImportError:
    print("RPi.GPIO or lib_st7789 is required. This is likely because the script is not running on a Raspberry Pi.")
    GPIO = None
    ST7789 = None


class GifPlayer:
    """
    A class to play animated GIFs on an ST7789 display.
    """

    def __init__(self, display_folder: str, background_color: Tuple[int, int, int] = (0, 0, 0)):
        """
        Initializes the GifPlayer.

        Args:
            display_folder: The folder containing the GIF files.
            background_color: The background color for the display (default: black).
        """
        self.display_folder = display_folder
        self.background_color = background_color
        self.gif_files: List[str] = []
        self.current_gif_index = 0
        self.stop_playback = False
        self.display = None

        # Initialize GPIO and display if running on a Raspberry Pi
        if GPIO and ST7789:
            GPIO.setmode(GPIO.BCM)
            self.display = ST7789()
            self.display.init()
        else:
            print("Not running on a Raspberry Pi or lib_st7789 not found. Display functionality disabled.")

        self._load_gif_files()

    def _load_gif_files(self):
        """Loads GIF files from the display folder."""
        try:
            if not os.path.exists(self.display_folder):
                raise FileNotFoundError(f"Folder not found: {self.display_folder}")

            self.gif_files = [
                f for f in os.listdir(self.display_folder)
                if f.endswith(".gif")
            ]

            if not self.gif_files:
                raise ValueError(f"No GIF files found in folder: {self.display_folder}")

        except (FileNotFoundError, ValueError) as e:
            print(f"Error loading GIF files: {e}")
            exit(1)

    def _set_background(self):
        """Sets the background color of the display."""
        if self.display:
            try:
                self.display.clear_display(self.background_color)
            except Exception as e:
                print(f"Error setting background color: {e}")

    def _display_frame(self, image: Image.Image):
        """Displays a single frame on the ST7789 display."""
        if not self.display:
            return

        try:
            pixels = list(image.getdata())
            display_width = self.display.width
            display_height = self.display.height

            # Pad the image if it's smaller than the display
            if image.width < display_width or image.height < display_height:
                pad_width = (display_width - image.width, 0)
                pad_height = (display_height - image.height, 0)
                image = ImageOps.pad(image, (pad_width, pad_height), method=Image.NEAREST, color=self.background_color)
                pixels = list(image.getdata())

            # Convert to RGB and send to display
            for i in range(0, len(pixels), display_width):
                self.display.put_pixel_data(list(pixels[i:i + display_width]))

        except Exception as e:
            print(f"Error displaying frame: {e}")

    def play_gif(self, gif_file: str):
        """Plays a single GIF file."""
        try:
            image = Image.open(os.path.join(self.display_folder, gif_file))
            if image.format == 'GIF':
                for frame in range(image.n_frames):
                    if self.stop_playback:
                        break
                    image.seek(frame)
                    self._display_frame(image)
                    duration = image.info.get('duration', 100)  # Default duration is 100ms
                    time.sleep(duration / 1000.0)
            else:
                print(f"{gif_file} is not a GIF file.")
                return

        except FileNotFoundError:
            print(f"GIF file not found: {gif_file}")
        except Exception as e:
            print(f"Error playing GIF: {e}")

    def play_all_gifs(self):
        """Plays all GIFs in a loop."""
        while not self.stop_playback:
            if self.gif_files:
                self.play_gif(self.gif_files[self.current_gif_index])
                self.current_gif_index = (self.current_gif_index + 1) % len(self.gif_files)
            else:
                print("No GIF files found.")
                break

    def signal_handler(self, sig, frame):
        """Handles SIGINT and SIGTERM signals for graceful exit."""
        print("Exiting gracefully...")
        self.stop_playback = True

    def run(self):
        """Starts the GIF playback."""
        signal.signal(signal.SIGINT, self.signal_handler)
        signal.signal(signal.SIGTERM, self.signal_handler)

        if self.display:
            self._set_background()
            self.play_all_gifs()
        else:
            print("Display functionality is disabled.")


if __name__ == "__main__":
    gif_folder = input("Enter the folder containing your GIFs: ").strip()
    background_red = int(input("Enter background red color (0-255): ") or 0)
    background_green = int(input("Enter background green color (0-255): ") or 0)
    background_blue = int(input("Enter background blue color (0-255): ") or 0)

    player = GifPlayer(gif_folder, (background_red, background_green, background_blue))
    player.run()

