# Reads temperature data from a UART sensor and logs it to a CSV file.
# Target: Raspberry Pi 3 Model B+

import serial
import time
import csv

# UART configuration
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1

# CSV log file
LOG_FILE = 'temperature_log.csv'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def initialize_csv_log(filename):
    """Initializes the CSV log file with a header."""
    try:
        with open(filename, 'w', newline='') as csvfile:
            csv_writer = csv.writer(csvfile)
            csv_writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])
    except IOError as e:
        print(f"Error initializing CSV file: {e}")

def read_temperature(serial_port):
    """Reads temperature data from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Warning: Malformed data received from sensor.")
        return None
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return (celsius * 9/5) + 32

def log_data(filename, timestamp, celsius, fahrenheit):
    """Logs the temperature data to the CSV file."""
    try:
        with open(filename, 'a', newline='') as csvfile:
            csv_writer = csv.writer(csvfile)
            csv_writer.writerow([timestamp, celsius, fahrenheit])
    except IOError as e:
        print(f"Error writing to CSV file: {e}")

def main():
    """Main function to read temperature and log data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if serial_connection is None:
        exit(1)

    initialize_csv_log(LOG_FILE)

    try:
        while True:
            temperature = read_temperature(serial_connection)
            if temperature is not None:
                fahrenheit = convert_to_fahrenheit(temperature)
                timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
                log_data(LOG_FILE, timestamp, temperature, fahrenheit)
                print(f"Logged: {timestamp}, {temperature}°C, {fahrenheit}°F")
            time.sleep(1)

    except KeyboardInterrupt:
        print("Exiting program.")

    finally:
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

