logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Serial port configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Alert thresholds
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        logging.info(f"Serial connection established on {port} at {baudrate} baud.")
        return ser
    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {port}: {e}")
        return None

def read_sensor_data(serial_connection):
    """Reads a line from the serial port and parses it."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                temperature, humidity = line.split(',')
                return float(temperature), float(humidity)
            except ValueError:
                logging.warning(f"Invalid data format received: {line}")
                return None, None
        else:
            return None, None
    except serial.SerialException as e:
        logging.error(f"Serial read error: {e}")
        return None, None

def check_alerts(temperature, humidity, temp_threshold, humidity_threshold):
    """Checks if temperature or humidity exceeds the defined thresholds."""
    if temperature is not None and humidity is not None:
        if temperature > temp_threshold:
            logging.warning(f"Temperature alert: {temperature:.1f}°C")
        if humidity > humidity_threshold:
            logging.warning(f"Humidity alert: {humidity:.1f}%")

def main():
    """Main function to read sensor data and log alerts."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        logging.error("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(serial_connection)

            if temperature is not None and humidity is not None:
                logging.info(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                check_alerts(temperature, humidity, TEMPERATURE_THRESHOLD, HUMIDITY_THRESHOLD)

            time.sleep(1)

    except KeyboardInterrupt:
        logging.info("Program terminated by user.")

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            logging.info("Serial connection closed.")

if __name__ == "__main__":
    main()

