# Switch mirroring with MCP23017 on Raspberry Pi Model 1
# Mirrors a mechanical switch input to an LED output
import time
from MCP23017_I2C import GPIO_CHIP

# I2C bus and expander address
I2C_BUS = 0
I2C_ADDRESS = 0x20

# Switch and LED pin configuration
SWITCH_PIN = 7
LED_PIN = 0

def initialize_gpio(gpio_chip):
    """Configure the switch and LED pins as inputs and outputs."""
    gpio_chip.setup(SWITCH_PIN, 'IN', 'PUD_UP')
    gpio_chip.setup(LED_PIN, 'OUT')

def read_switch_state(gpio_chip):
    """Read the current state of the switch pin."""
    return gpio_chip.input(SWITCH_PIN)

def update_led(gpio_chip, switch_state):
    """Turn the LED on or off based on the switch state."""
    if switch_state == 0:
        gpio_chip.output(LED_PIN, 1)
        print('Led ON')
    else:
        gpio_chip.output(LED_PIN, 0)
        print('Led OFF')

def mirror_switch(gpio_chip):
    """Continuously read the switch and mirror its state to the LED."""
    previous_state = read_switch_state(gpio_chip)
    while True:
        try:
            current_state = read_switch_state(gpio_chip)
            if current_state != previous_state:
                update_led(gpio_chip, current_state)
                previous_state = current_state
            time.sleep(0.1)
        except Exception as error:
            print(f'Error: {error}')
            time.sleep(1)

def main():
    """Main function to initialize and run the switch mirroring."""
    try:
        gpio_chip = GPIO_CHIP(I2C_BUS, I2C_ADDRESS)
        initialize_gpio(gpio_chip)
        mirror_switch(gpio_chip)
    except Exception as error:
        print(f'Fatal error: {error}')
    finally:
        print('Program terminated.')

if __name__ == "__main__":
    main()

