import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this is your custom communication library

# Constants
DEFAULT_LOG_FILE = "data.log"
PROMPT = "JAYES@ROVER53:\t"

# Configuration
GPIO.setwarnings(False)
GPIO.setmode(GPIO.BCM)

# Global Variables
is_running = False
log_file_path = DEFAULT_LOG_FILE
receive_thread = None

# Help messages for commands
help_messages = {
    "help": "Call 'help <command>' to see information about the command.\nCommands:\n\t-display\n\t-help\n\t-send\n\t-start\n\t-exit\n\t-write",
    "start": "Help for 'start':\nStarts listening to the ports and saves data to a file. Usage: start <filename>",
    "exit": "Help for 'exit':\nCloses this server.",
    "display": "Help for 'display':\nDisplays the data stored in the file. Usage: display",
    "send": "Help for 'send':\nSends the following string through the DOGProtocol. Usage: send <string>",
    "write": "Help for 'write':\nWrites the following string directly to the log file. Usage: write <string>",
}


def log_message(message):
    """Appends a message to the log file."""
    try:
        with open(log_file_path, 'a') as log_file:
            log_file.write(message + "\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def receive_data():
    """Continuously receives data and logs it to the file."""
    global is_running
    try:
        while is_running:
            data = DOG.receive()  # Your custom receive function
            if data:
                log_message(data)
            time.sleep(0.1)  # Add a small delay to avoid excessive CPU usage
    except Exception as e:
        print(f"Error in receive thread: {e}")
    finally:
        print("Receive thread stopped.")


def start_receiving(filename):
    """Starts the data receiving thread."""
    global is_running, receive_thread, log_file_path

    if is_running:
        print("Already running. Stop first.")
        return

    log_file_path = filename
    try:
        with open(log_file_path, 'a') as _:  # Check if file exists and can be written to
            pass
    except IOError as e:
        print(f"Error creating/writing to log file: {e}")
        return

    is_running = True
    receive_thread = threading.Thread(target=receive_data, name='ReceiveThread', daemon=True)
    receive_thread.start()
    print(f"Receiving data and logging to '{log_file_path}'")


def stop_receiving():
    """Stops the data receiving thread and cleans up."""
    global is_running, receive_thread
    is_running = False

    if receive_thread and receive_thread.is_alive():
        receive_thread.join()  # Wait for the thread to finish
    receive_thread = None

    print("Data logging stopped.")



def send_data(data_string):
    """Sends data using the DOGProtocol."""
    if not is_running:
        print("Not running. Start receiving first.")
        return
    try:
        DOG.send(data_string) # Your custom send function
        print(f"Sent: {data_string}")
    except Exception as e:
        print(f"Error sending data: {e}")


def write_to_log(log_string):
    """Writes a string directly to the log file."""
    if not is_running:
        print("Not running. Start receiving first.")
        return
    log_message(log_string)
    print(f"Wrote to log: {log_string}")



def display_log():
    """Displays the contents of the log file."""
    if not is_running:
        print("Not running. Start receiving first.")
        return
    try:
        with open(log_file_path, 'r') as log_file:
            print(log_file.read())
    except IOError as e:
        print(f"Error reading log file: {e}")


def handle_command(command):
    """Processes a given command."""
    parts = command.split()
    if not parts:
        return

    command_name = parts[0].lower()

    try:
        if command_name == "help":
            if len(parts) == 2 and parts[1] in help_messages:
                print(help_messages[parts[1]])
            else:
                print(help_messages["help"])
        elif command_name == "start":
            if len(parts) == 2:
                start_receiving(parts[1])
            else:
                print(help_messages["start"])

        elif command_name == "send":
            send_data(" ".join(parts[1:]))

        elif command_name == "write":
            write_to_log(" ".join(parts[1:]))

        elif command_name == "display":
            display_log()

        elif command_name == "exit":
            stop_receiving()
            print("Exiting.")
            sys.exit(0)

        else:
            print(f"Unknown command: {command_name}")

    except Exception as e:
        print(f"Error executing command: {e}")


def main():
    """Main program loop."""
    try:
        while True:
            try:
                command = input(PROMPT).strip()
                handle_command(command)
            except KeyboardInterrupt:
                print("\nKeyboardInterrupt")
            except Exception as e:
                print(f"Unexpected error: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit


if __name__ == "__main__":
    main()

