import RPi.GPIO as GPIO
from flask import Flask, render_template_string
import os
import signal
import atexit

# Constants
LED_PIN = 17
SERVER_PORT = 8080
SERVER_HOST = '0.0.0.0'

# Initialize Flask application
app = Flask(__name__)

# LED setup function
def setup_led(pin):
    """Sets up the GPIO pin for the LED."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        GPIO.setwarnings(False)  # Suppress warnings
        return True
    except Exception as e:
        print(f"Error setting up LED: {e}")
        return False

# LED control functions
def turn_led_on(pin):
    """Turns the LED on."""
    try:
        GPIO.output(pin, GPIO.HIGH)
        return True
    except Exception as e:
        print(f"Error turning LED on: {e}")
        return False

def turn_led_off(pin):
    """Turns the LED off."""
    try:
        GPIO.output(pin, GPIO.LOW)
        return True
    except Exception as e:
        print(f"Error turning LED off: {e}")
        return False

# Route functions
def get_index_page():
    """Returns the main index page."""
    template = """
    <h1>Control LED</h1>
    <a href="/light_on">Turn ON</a> | <a href="/light_off">Turn OFF</a>
    """
    return render_template_string(template)

def get_light_on_page(pin):
    """Turns the LED on and returns the on page."""
    if turn_led_on(pin):
        template = """
        <h1>LED is ON</h1>
        <a href="/">Back</a>
        """
        return render_template_string(template)
    else:
        return "Error turning LED on", 500

def get_light_off_page(pin):
    """Turns the LED off and returns the off page."""
    if turn_led_off(pin):
        template = """
        <h1>LED is OFF</h1>
        <a href="/">Back</a>
        """
        return render_template_string(template)
    else:
        return "Error turning LED off", 500

# Flask route definitions
@app.route('/')
def index():
    """Index route."""
    return get_index_page()

@app.route('/light_on')
def light_on():
    """Light on route."""
    return get_light_on_page(LED_PIN)

@app.route('/light_off')
def light_off():
    """Light off route."""
    return get_light_off_page(LED_PIN)

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    """Handles termination signals."""
    print("Shutting down gracefully...")
    GPIO.cleanup()
    exit(0)

# Register signal handlers
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Main execution block
if __name__ == '__main__':
    # Attempt to setup the LED
    if not setup_led(LED_PIN):
        print("LED setup failed. Exiting.")
        exit(1)

    # Run the Flask app
    try:
        app.run(host=SERVER_HOST, port=SERVER_PORT, debug=False)
    except Exception as e:
        print(f"Error running Flask app: {e}")
    finally:
        # Ensure GPIO cleanup on exit
        GPIO.cleanup()

