import RPi.GPIO as GPIO
import time
import sys

# Set GPIO numbering mode (BCM is recommended)
GPIO.setmode(GPIO.BCM)

# Define the GPIO pin connected to the fan's PWM control
FAN_PIN = 12

# Set up the fan pin as output and initially turn the fan off
try:
    GPIO.setup(FAN_PIN, GPIO.OUT, initial=GPIO.LOW)
except Exception as e:
    print(f"Error setting up GPIO: {e}")
    sys.exit(1)

# Create a PWM instance for fan control (25kHz frequency)
try:
    fan = GPIO.PWM(FAN_PIN, 25000)
    fan.start(0)  # Start with 0% duty cycle (fan off)
except Exception as e:
    print(f"Error creating PWM instance: {e}")
    GPIO.cleanup()
    sys.exit(1)


def set_fan_speed(speed_percentage):
    """Sets the fan speed as a percentage of maximum speed."""
    try:
        speed_percentage = float(speed_percentage)  # Ensure input is a number
        if 0 <= speed_percentage <= 100:
            fan.ChangeDutyCycle(speed_percentage)
            print(f"Fan speed set to {speed_percentage:.2f}%")
        else:
            print("Invalid speed. Please enter a value between 0 and 100.")
    except ValueError:
        print("Invalid input. Please enter a number.")
    except Exception as e:
        print(f"Error setting fan speed: {e}")


def main():
    """Main function to continuously get fan speed from user."""
    try:
        while True:
            try:
                fan_speed = input("Enter fan speed (0-100), or 'q' to quit: ")
                if fan_speed.lower() == 'q':
                    break  # Exit loop if user enters 'q'
                set_fan_speed(fan_speed)
            except KeyboardInterrupt:  # Handle Ctrl+C gracefully
                print("\nFan control interrupted. Exiting...")
                break
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Clean up GPIO settings before exiting
        fan.stop()
        GPIO.cleanup()
        print("GPIO cleanup complete.")


if __name__ == "__main__":
    main()

