import RPi.GPIO as GPIO
import random
import time

# Configuration constants
LED_PIN = 18
LOW_QUALITY_THRESHOLD = 50
READING_DELAY = 2

def setup_gpio(pin):
    """Sets up the GPIO pin for the LED."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pin, GPIO.OUT)

def read_water_quality():
    """Simulates reading water quality data."""
    # Introduce a small chance of failure to demonstrate error handling
    if random.random() < 0.1:
        raise ValueError("Sensor read failed")
    return random.randint(0, 100)

def control_led(pin, quality_level):
    """Controls the LED based on water quality."""
    if quality_level < LOW_QUALITY_THRESHOLD:
        GPIO.output(pin, GPIO.HIGH)  # Turn LED on
        print("Water quality low! LED is ON")
    else:
        GPIO.output(pin, GPIO.LOW)   # Turn LED off
        print("Water quality normal. LED is OFF")

def main():
    """Main function to run the water quality monitoring system."""
    try:
        setup_gpio(LED_PIN)
        print("Water quality monitoring system started...")
        for _ in range(5):
            try:
                water_quality = read_water_quality()
                print(f"Water quality: {water_quality}%")
                control_led(LED_PIN, water_quality)
                time.sleep(READING_DELAY)
            except ValueError as e:
                print(f"Error reading sensor: {e}")
                # Retry once
                try:
                    water_quality = read_water_quality()
                    print(f"Retry: Water quality: {water_quality}%")
                    control_led(LED_PIN, water_quality)
                except ValueError as retry_error:
                    print(f"Error reading sensor after retry: {retry_error}")

        print("Water quality monitoring system finished.")

    except KeyboardInterrupt:
        print("\nSystem stopped by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO on exit
        print("GPIO cleanup completed.")

if __name__ == "__main__":
    main()

