import socket
import time
import json
import os
import signal
import sys

# Constants
DEFAULT_PORT = 9099
GPS_READ_TIMEOUT = 2  # seconds

# Global variables
gps_enabled = False
gps_port = "/dev/ttyAMA0"
gps_baudrate = 9600
gps_timeout = GPS_READ_TIMEOUT
gps_socket = None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    print('You pressed Ctrl+C!')
    shutdown()
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# --- GPS Functions ---
def read_gps_data(uart_port, baudrate, timeout):
    """Reads data from the GPS module."""
    try:
        import serial
        ser = serial.Serial(uart_port, baudrate=baudrate, timeout=timeout)
        line = ser.readline().decode('utf-8', errors='ignore').strip()
        ser.close()
        return line
    except serial.SerialException as e:
        print(f"Error reading from GPS: {e}", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Unexpected error reading GPS: {e}", file=sys.stderr)
        return None

def parse_gps_data(data):
    """Parses GPS data to extract latitude and longitude."""
    if data and "," in data:
        try:
            parts = data.split(",")
            if len(parts) >= 2:
                lat = parts[0].strip()
                lon = parts[1].strip()
                return lat, lon
        except Exception as e:
            print(f"Error parsing GPS data: {e}", file=sys.stderr)
    return None, None

def get_gps_position():
    """Retrieves the current GPS position."""
    data = read_gps_data(gps_port, gps_baudrate, gps_timeout)
    if data:
        lat, lon = parse_gps_data(data)
        if lat and lon:
            return lat, lon
    return None, None

# --- Command Handling ---
def handle_command(command):
    """Processes incoming commands."""
    global gps_enabled
    if command == "start":
        gps_enabled = True
        print("GPS tracking started.")
        return True
    elif command == "stop":
        gps_enabled = False
        print("GPS tracking stopped.")
        return True
    elif command == "report":
        if gps_enabled:
            lat, lon = get_gps_position()
            if lat and lon:
                print(f"Latitude: {lat}")
                print(f"Longitude: {lon}")
                return True
            else:
                print("No GPS data available.")
                return False
        else:
            print("GPS tracking is not active.")
            return False
    else:
        print("Invalid command.")
        return False

# --- Networking Functions ---
def create_socket(port):
    """Creates and binds a socket."""
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1) # Avoid address already in use error
        s.bind(('127.0.0.1', port))
        return s
    except socket.error as e:
        print(f"Error creating socket: {e}", file=sys.stderr)
        return None

def listen(port):
    """Listens for incoming connections."""
    global gps_socket
    try:
        gps_socket = create_socket(port)
        if gps_socket:
            gps_socket.listen(1)
            print(f"Listening on port {port}...")
            return True
        else:
            return False
    except Exception as e:
        print(f"Error listening on socket: {e}", file=sys.stderr)
        return False

def accept_connection():
    """Accepts an incoming connection."""
    try:
        conn, addr = gps_socket.accept()
        print(f"Connection from {addr}")
        return conn
    except socket.error as e:
        print(f"Error accepting connection: {e}", file=sys.stderr)
        return None

def send_response(conn, response):
    """Sends a response to the client."""
    try:
        conn.sendall(response.encode())
    except socket.error as e:
        print(f"Error sending data: {e}", file=sys.stderr)
    finally:
        conn.close()

# --- Main Function ---
def main():
    """Main function to run the GPS tracking server."""
    if not listen(DEFAULT_PORT):
        print("Failed to start server. Exiting.", file=sys.stderr)
        return

    try:
        while True:
            conn = accept_connection()
            if conn:
                data = conn.recv(1024).decode().strip()
                if data:
                    print(f"Received: {data}")
                    if handle_command(data):
                        send_response(conn, "OK")
                    else:
                        send_response(conn, "ERROR")
    except KeyboardInterrupt:
        print("Server interrupted. Shutting down...")
    finally:
        shutdown()

# --- Cleanup ---
def shutdown():
    """Closes the socket and cleans up resources."""
    global gps_socket
    print("Shutting down server...")
    if gps_socket:
        gps_socket.close()
        print("Socket closed.")

if __name__ == "__main__":
    main()

