SOIL_SENSOR_PIN = 2
LED_INDICATOR_PIN = 17

# Define the delay between readings in seconds
READING_DELAY = 2

def initialize_gpio():
    """Set up the GPIO pins for the soil sensor and LED."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(SOIL_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    GPIO.setup(LED_INDICATOR_PIN, GPIO.OUT)

