            update_led(soil_is_dry)
            display_status(soil_is_dry)
            time.sleep(READING_DELAY)
    except KeyboardInterrupt:
        print('\nProgram terminated by user.')
    finally:
        GPIO.cleanup()
        print('GPIO resources released.')

if __name__ == "__main__":
    initialize_gpio()
    main_loop()

