import RPi.GPIO as GPIO
import time
from datetime import datetime

# Define the GPIO pin connected to the relay
RELAY_PIN = 17

# Define the sunrise and sunset times (24-hour format)
SUNRISE_TIME = "07:00:00"
SUNSET_TIME = "19:00:00"

def setup_gpio(pin):
    """Sets up the GPIO pin for relay control."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(pin, GPIO.OUT)
        GPIO.output(pin, GPIO.HIGH)  # Initially close the door
        print("GPIO setup complete.")
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        exit()

def is_time_between(start_time, end_time, current_time):
    """Checks if the current time is between the start and end times."""
    try:
        # Convert times to datetime objects
        start = datetime.strptime(start_time, "%H:%M:%S").time()
        end = datetime.strptime(end_time, "%H:%M:%S").time()
        current = datetime.strptime(current_time, "%H:%M:%S").time()

        # Compare times, considering hours and minutes only
        if start <= end:
            return start <= current <= end
        else:  # Handle cases where the end time is before the start time (e.g., sunset to sunrise)
            return start <= current or current <= end
    except ValueError as e:
        print(f"Error parsing time: {e}")
        return False

def control_door(pin, open_door):
    """Controls the door (opens or closes) based on the 'open_door' parameter."""
    try:
        if open_door:
            GPIO.output(pin, GPIO.LOW)  # Activate relay to open the door
            print("Opening door...")
        else:
            GPIO.output(pin, GPIO.HIGH) # Deactivate relay to close the door
            print("Closing door...")
    except Exception as e:
        print(f"Error controlling door: {e}")

def main():
    """Main function to control the chicken coop door."""
    setup_gpio(RELAY_PIN)

    try:
        while True:
            current_time = datetime.now().time().strftime("%H:%M:%S")

            if is_time_between(SUNRISE_TIME, SUNSET_TIME, current_time):
                control_door(RELAY_PIN, True)  # Open the door
            else:
                control_door(RELAY_PIN, False) # Close the door

            time.sleep(60)  # Check every minute

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.cleanup()  # Clean up GPIO settings
        print("GPIO cleanup complete.")

if __name__ == "__main__":
    main()

