# A script to monitor soil moisture and control a water pump on Raspberry Pi Zero W.

import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Define constants
I2C_BUS = 1
RELAY_GPIO_PIN = 17
MOISTURE_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_seesaw(i2c_bus):
    """Initialize the Seesaw soil moisture sensor."""
    try:
        sensor = adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x36)
        return sensor
    except Exception as e:
        print(f"Error initializing Seesaw sensor: {e}")
        return None

def initialize_gpio(relay_pin):
    """Initialize the GPIO pin for the relay."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(relay_pin, GPIO.OUT)
        GPIO.output(relay_pin, GPIO.LOW)  # Initially off
    except Exception as e:
        print(f"Error initializing GPIO: {e}")

def read_moisture_level(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        moisture = sensor.moisture_read()
        return moisture
    except Exception as e:
        print(f"Error reading moisture: {e}")
        return None

def control_water_pump(relay_pin, moisture_level, threshold):
    """Control the water pump based on the moisture level."""
    try:
        if moisture_level is not None:
            if moisture_level < threshold:
                GPIO.output(relay_pin, GPIO.HIGH)  # Turn on pump
                pump_status = "ON"
            else:
                GPIO.output(relay_pin, GPIO.LOW)   # Turn off pump
                pump_status = "OFF"
            return pump_status
        else:
            return "UNKNOWN"
    except Exception as e:
        print(f"Error controlling pump: {e}")
        return "ERROR"

def main():
    """Main function to run the soil moisture monitoring and pump control."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_seesaw(i2c_bus)
    if sensor is None:
        return

    initialize_gpio(RELAY_GPIO_PIN)

    try:
        while True:
            moisture = read_moisture_level(sensor)
            pump_status = control_water_pump(RELAY_GPIO_PIN, moisture, MOISTURE_THRESHOLD)

            if moisture is not None:
                print(f"Moisture: {moisture}, Pump: {pump_status}")
            else:
                print("Failed to read moisture level.")

            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Program terminated by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # Ensure pump is off and GPIO is cleaned up on exit
        GPIO.output(RELAY_GPIO_PIN, GPIO.LOW)
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

