import serial
import RPi.GPIO as GPIO
import time
import logging
import os
import atexit

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
GSM_PORT = os.getenv("GSM_PORT", "/dev/serial0")  # Use environment variable or default
BAUDRATE = int(os.getenv("BAUDRATE", "115200"))
TIMEOUT = int(os.getenv("TIMEOUT", "2"))
MESSAGE_STORAGE = os.getenv("MESSAGE_STORAGE", "SM")  # SIM card storage
TCP_SERVER_IP = os.getenv("TCP_SERVER_IP", "192.168.100.12")
TCP_SERVER_PORT = int(os.getenv("TCP_SERVER_PORT", "50"))
GPS_READ_INTERVAL = int(os.getenv("GPS_READ_INTERVAL", "10"))
POWER_PIN = int(os.getenv("POWER_PIN", "4"))  # GPIO pin for power control
RETRY_COUNT = int(os.getenv("RETRY_COUNT", "3"))  # Number of retries for AT commands


class GSMModule:
    """
    A class to encapsulate GSM module functionalities, including sending messages,
    managing GPS, reading stored messages, and sending data over TCP.
    """

    def __init__(self, port=GSM_PORT, baudrate=BAUDRATE, timeout=TIMEOUT, power_pin=POWER_PIN):
        """
        Initializes the GSMModule object.

        Args:
            port (str): The serial port to use. Defaults to GSM_PORT.
            baudrate (int): The baud rate for serial communication. Defaults to BAUDRATE.
            timeout (int): The timeout for serial communication in seconds. Defaults to TIMEOUT.
            power_pin (int): The GPIO pin connected to the power control of the GSM module. Defaults to POWER_PIN.
        """
        self.port_name = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.port = None  # Initialize port to None
        self.power_pin = power_pin
        self.retries = RETRY_COUNT  # Number of retries for AT commands

        # Initialize GPIO
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(self.power_pin, GPIO.OUT)
        GPIO.output(self.power_pin, GPIO.HIGH)  # Turn on the GSM module
        time.sleep(2)  # Give it some time to power on

        self._connect_serial()  # Establish serial connection

        atexit.register(self.close)  # Ensure cleanup on exit

        if not self.port:
            logging.error("Failed to initialize GSM module. Serial connection failed.")
            raise RuntimeError("Failed to initialize GSM module.")

        if not self.attach():
            logging.error("Failed to attach to the network.")
            raise RuntimeError("Failed to attach to the network.")

        if not self.set_message_storage(MESSAGE_STORAGE):
            logging.warning(f"Failed to set message storage to {MESSAGE_STORAGE}. SMS functionality may be limited.")

        self.set_gps_reporting(GPS_READ_INTERVAL)

    def _connect_serial(self):
        """
        Establishes the serial connection to the GSM module.  Handles potential errors during initialization.
        """
        try:
            self.port = serial.Serial(self.port_name, baudrate=self.baudrate, timeout=self.timeout)
            logging.info(f"Connected to GSM module on {self.port_name} at {self.baudrate} baud.")
            return True
        except serial.SerialException as e:
            logging.error(f"Error opening serial port {self.port_name}: {e}")
            return False

    def _with_serial(self, func, *args, **kwargs):
        """
        A decorator to handle serial communication errors. Retries the function if it fails.
        """
        for attempt in range(self.retries):
            try:
                if self.port and func(self, *args, **kwargs):
                    return True
                else:
                    logging.warning(f"Function {func.__name__} failed. Retrying ({attempt + 1}/{self.retries})...")
                    time.sleep(1)  # Wait before retrying
            except serial.SerialException as e:
                logging.error(f"Serial communication error: {e}. Retrying ({attempt + 1}/{self.retries})...")
                time.sleep(1)
        logging.error(f"Function {func.__name__} failed after multiple retries.")
        return False

    def _send_at_command(self, command, read_response=True, delay=0.1, expected_reply="OK"):
        """
        Sends an AT command to the GSM module and reads the response.

        Args:
            command (str): The AT command to send.
            read_response (bool): Whether to read the response from the module. Defaults to True.
            delay (float): Delay in seconds after sending the command before reading. Defaults to 0.1.
            expected_reply (str): The expected reply from the module. Defaults to "OK".

        Returns:
            str: The response from the GSM module, or None if an error occurred.
        """
        if not self.port:
            logging.error("Serial port not initialized.")
            return None

        try:
            self.port.write((command + '\r\n').encode())
            time.sleep(delay)
            if read_response:
                response = self.read_response(expected_reply)
                if response:
                    logging.debug(f"Command: {command}, Response: {response}")
                    return response
                else:
                    logging.warning(f"No response received for command: {command}")
                    return None
            else:
                return True  # Command sent successfully, no response needed
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None

    def read_response(self, expected_reply="OK", timeout=TIMEOUT):
        """
        Reads the response from the GSM module. Handles different expected replies.

        Args:
            expected_reply (str): The expected reply from the module. Defaults to "OK".
            timeout (int): Timeout in seconds to wait for a response.

        Returns:
            str: The response from the GSM module, or None if an error occurred or timeout occurred.
        """
        if not self.port:
            logging.error("Serial port not initialized.")
            return None

        try:
            response = self.port.read(1000).decode('utf-8', errors='ignore')  # Read up to 1000 bytes
            logging.debug(f"Raw response: {response}")

            if not response:
                logging.warning("No response received.")
                return None

            if expected_reply == "OK":
                if "OK" in response or "ok" in response:
                    return "OK"
                else:
                    logging.warning(f"Expected 'OK', but got: {response}")
                    return None
            elif expected_reply == "ERROR":
                if "ERROR" in response or "error" in response:
                    return "ERROR"
                else:
                    logging.warning(f"Expected 'ERROR', but got: {response}")
                    return None
            elif expected_reply == "":  # No specific expected reply, return the raw response
                return response
            else:  # Custom expected reply
                if expected_reply in response:
                    return expected_reply
                else:
                    logging.warning(f"Expected '{expected_reply}', but got: {response}")
                    return None
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"Error reading response: {e}")
            return None

    def attach(self):
        """
        Attaches to the GSM network.

        Returns:
            bool: True if the attachment was successful, False otherwise.
        """
        @self._with_serial
        def attach_once(self):
            logging.info("Attaching to the network...")
            if self._send_at_command("AT+CGATT=1", expected_reply="OK"):
                logging.info("Attached to the network.")
                return True
            else:
                logging.warning("Failed to attach to the network.")
                return False
        return attach_once(self)

    def detach(self):
        """
        Detaches from the GSM network.

        Returns:
            bool: True if the detachment was successful, False otherwise.
        """
        @self._with_serial
        def detach_once(self):
            logging.info("Detaching from the network...")
            if self._send_at_command("AT+CGATT=0", expected_reply="OK"):
                logging.info("Detached from the network.")
                return True
            else:
                logging.warning("Failed to detach from the network.")
                return False
        return detach_once(self)

    def set_message_storage(self, storage):
        """
        Sets the preferred message storage location.

        Args:
            storage (str): The storage location.

        Returns:
            bool: True if the storage location was set successfully, False otherwise.
        """
        @self._with_serial
        def set_storage_once(self, storage):
            logging.info(f"Setting message storage to {storage}...")
            command = f'AT+CPMS="{storage}","{storage}","{storage}"'
            if self._send_at_command(command, expected_reply="OK"):
                logging.info(f"Message storage set to {storage}.")
                return True
            else:
                logging.warning(f"Failed to set message storage to {storage}.")
                return False
        return set_storage_once(self, storage)

    def read_stored_messages(self):
        """
        Reads all stored messages from the preferred storage location.

        Returns:
            str: The response containing the stored messages, or None if an error occurred.
        """
        @self._with_serial
        def read_messages_once(self):
            logging.info("Reading stored messages...")
            if self._send_at_command("AT+CMGF=1", expected_reply="OK"):  # Text mode
                response = self._send_at_command("AT+CMGL=\"ALL\"", expected_reply="OK", read_response=False)
                if response:
                    logging.info("Stored messages read successfully.")
                    return response
                else:
                    logging.warning("Failed to read stored messages.")
                    return None
            else:
                logging.warning("Failed to set text mode for reading messages.")
                return None
        return read_messages_once(self)

    def send_message(self, number, message):
        """
        Sends an SMS message to the specified phone number.

        Args:
            number (str): The phone number to send the message to.
            message (str): The message to send.

        Returns:
            bool: True if the message was sent successfully, False otherwise.
        """
        @self._with_serial
        def send_message_once(self, number, message):
            logging.info(f"Sending message to {number}: {message}...")
            if self._send_at_command("AT+CMGF=1", expected_reply="OK"):  # Text mode
                if self._send_at_command(f'AT+CMGS="{number}"', expected_reply=">"):
                    if self._send_at_command(message, expected_reply="", delay=1):
                        logging.info(f"Message sent to {number}.")
                        return True
                    else:
                        logging.warning(f"Failed to send message to {number}.")
                        return False
                else:
                    logging.warning(f"Failed to send number to {number}.")
                    return False
            else:
                logging.warning("Failed to set text mode for sending message.")
                return False
        return send_message_once(self, number, message)

    def control_gps(self, enable=True):
        """
        Turns the GPS module on or off.

        Args:
            enable (bool): True to turn GPS on, False to turn it off. Defaults to True.

        Returns:
            bool: True if the GPS was controlled successfully, False otherwise.
        """
        @self._with_serial
        def control_gps_once(self, enable):
            if enable:
                logging.info("Turning GPS ON...")
                command = "AT+GPS=1"
                expected_reply = "OK"
            else:
                logging.info("Turning GPS OFF...")
                command = "AT+GPS=0"
                expected_reply = "OK"

            if self._send_at_command(command, expected_reply=expected_reply):
                logging.info(f"GPS turned {'ON' if enable else 'OFF'}.")
                return True
            else:
                logging.warning(f"Failed to turn GPS {'ON' if enable else 'OFF'}.")
