import serial
import time
import datetime
import signal
import sys

# Configuration
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
READ_TIMEOUT = 1  # seconds
LOG_FILE = 'co2_readings_log.txt'
SAMPLE_INTERVAL = 5  # seconds

# Global variable to track if the program should exit
running = True

def signal_handler(sig, frame):
    """Handles Ctrl+C (SIGINT) and SIGTERM signals."""
    global running
    print("Exiting program...")
    running = False

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error initializing serial port: {e}", file=sys.stderr)
        return None

def read_co2_concentration(serial_port):
    """Reads CO2 concentration from the serial port."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return int(line)
        else:
            return None
    except ValueError:
        print("Invalid data received from sensor.", file=sys.stderr)
        return None
    except Exception as e:
        print(f"Error reading from serial port: {e}", file=sys.stderr)
        return None

def log_co2_reading(log_file, timestamp, co2_value):
    """Logs the CO2 reading to a file."""
    try:
        with open(log_file, 'a') as file:
            file.write(f"{timestamp}, {co2_value} ppm\n")
    except IOError as e:
        print(f"Error writing to log file: {e}", file=sys.stderr)

def main():
    """Main function to read CO2 data and log it."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, READ_TIMEOUT)
    if serial_connection is None:
        sys.exit(1)

    try:
        while running:
            co2_value = read_co2_concentration(serial_connection)
            if co2_value is not None:
                timestamp = datetime.datetime.now().isoformat()
                print(f"{timestamp}: {co2_value} ppm")
                log_co2_reading(LOG_FILE, timestamp, co2_value)
            time.sleep(SAMPLE_INTERVAL)
    finally:
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

