        return None


def read_gps_data(serial_port):
    """Reads a line of data from the GPS module."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None


def parse_gps_data(nmea_data):
    """Parses the NMEA data to extract latitude, longitude, and altitude."""
    if nmea_data.startswith('$GPGGA'):
        try:
            msg = pynmea2.parse(nmea_data)
            latitude = msg.latitude
            longitude = msg.longitude
            altitude = msg.altitude
            fix_quality = msg.fix_quality
            return latitude, longitude, altitude, fix_quality
        except pynmea2.ParseError as e:
            print(f"Error parsing NMEA data: {e}")
            return None, None, None, None
    return None, None, None, None


def get_timestamp():
    """Generates an ISO 8601 timestamp."""
    return datetime.datetime.now().isoformat()


def log_coordinates(timestamp, latitude, longitude, altitude, log_file):
    """Logs the coordinates to a file with a timestamp."""
    try:
        with open(log_file, 'a') as file:
            file.write(f"{timestamp}, {latitude}, {longitude}, {altitude}\n")
    except IOError as e:
        print(f"Error writing to log file: {e}")


def print_coordinates(latitude, longitude):
    """Prints the coordinates to the console."""
    print(f"Latitude: {latitude}, Longitude: {longitude}")


