    """Main function to read, parse, and log GPS data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            nmea_data = read_gps_data(serial_connection)

            if nmea_data:
                latitude, longitude, altitude, fix_quality = parse_gps_data(nmea_data)

                if latitude is not None and longitude is not None and fix_quality == 1:
                    timestamp = get_timestamp()
                    log_coordinates(timestamp, latitude, longitude, altitude, LOG_FILE)
                    print_coordinates(latitude, longitude)

            time.sleep(1)

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        serial_connection.close()
        print("Serial port closed.")


if __name__ == "__main__":
    main()

