DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DEFAULT_TIMEOUT = 1
MODEL_NAME = 'Web2uart Control'
DATA_STORE: List[dict] = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]
next_id = 3
DATA_STORE_LOCK = threading.Lock()

serial_port = DEFAULT_SERIAL_PORT
baudrate = DEFAULT_BAUDRATE
timeout = DEFAULT_TIMEOUT


class SerialConnection:
    """Manages the serial connection thread safely."""

    def __init__(self, port: str, baudrate: int, timeout: int):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self.lock = threading.Lock()
        self.is_open = False

    def open(self) -> bool:
        """Opens the serial port in a thread-safe manner."""
        with self.lock:
            if self.is_open:
                return True
            try:
                self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
                self.is_open = True
                logging.info(f"Serial port {self.port} opened successfully.")
                return True
            except serial.SerialException as e:
                logging.error(f"Failed to open serial port {self.port}: {e}")
                self.ser = None
                return False

    def close(self) -> None:
        """Closes the serial port in a thread-safe manner."""
        with self.lock:
            if self.ser and self.is_open:
                try:
                    self.ser.close()
                    self.is_open = False
                    logging.info(f"Serial port {self.port} closed successfully.")
                except serial.SerialException as e:
                    logging.error(f"Failed to close serial port {self.port}: {e}")

    def is_available(self) -> bool:
        """Checks if the serial port is open."""
        with self.lock:
            return self.is_open

    def send(self, message: str) -> bool:
        """Sends a message over the serial port in a thread-safe manner."""
        with self.lock:
            if not self.is_open:
                logging.warning("Serial port not open. Cannot send message.")
                return False
            try:
                encoded_message = message.encode('utf-8')
                self.ser.write(encoded_message)
                logging.debug(f"Sent: {message}")
                return True
            except serial.SerialException as e:
                logging.error(f"Failed to send message '{message}' via serial port {self.port}: {e}")
                return False

    def receive(self) -> str | None:
        """Receives data from the serial port in a thread-safe manner."""
        with self.lock:
            if not self.is_open:
                logging.warning("Serial port not open. Cannot receive data.")
                return None
            try:
                response = self.ser.readline().decode('utf-8', errors='ignore').strip()
                logging.debug(f"Received: {response}")
                return response
            except serial.SerialException as e:
                logging.error(f"Failed to receive data from serial port {self.port}: {e}")
                return None


serial_connection = SerialConnection(DEFAULT_SERIAL_PORT, DEFAULT_BAUDRATE, DEFAULT_TIMEOUT)


def get_serial_connection() -> SerialConnection:
    """Returns the global serial connection instance."""
    return serial_connection


def get_model_name() -> str:
    """Returns the model name."""
    return MODEL_NAME


def get_data_store() -> List[dict]:
    """Returns a copy of the data store, acquiring a lock."""
    with DATA_STORE_LOCK:
        return list(DATA_STORE)


def get_next_id() -> int:
    """Generates and returns a new unique ID, acquiring a lock."""
    global next_id
    with DATA_STORE_LOCK:
        next_id += 1
        return next_id - 1


@app.route('/model', methods=['GET'])
def model() -> Response:
    """Returns the model name."""
    return Response(f"{get_model_name()}\n", mimetype='text/plain')


@app.route('/version', methods=['GET'])
def version() -> Response:
    """Queries the connected device for its version information."""
    if not serial_connection.open():
        return Response("Error: Serial port not open\n", status=500, mimetype='text/plain')

    if not serial_connection.send("*IDN?\n"):
        serial_connection.close()
        return Response("Error: Failed to send query\n", status=500, mimetype='text/plain')

    response = serial_connection.receive()
    serial_connection.close()

    if response:
        return Response(response + "\n", mimetype='text/plain')
    else:
        return Response("Error: No response received\n", status=504, mimetype='text/plain')


@app.route('/getdata', methods=['GET'])
def get_data() -> jsonify:
    """Returns the entire data store as JSON."""
    return jsonify(get_data_store())


@app.route('/getdata/<int:item_id>', methods=['GET'])
def get_item(item_id: int) -> jsonify | Response:
    """Returns a specific item from the data store as JSON, or 404 if not found."""
    data_store = get_data_store()
    found_item = next((item for item in data_store if item['id'] == item_id), None)

    if found_item:
        return jsonify(found_item)
    else:
        abort(404)


@app.route('/getset/<int:item_id>/<name>', methods=['GET'])
def set_item_name(item_id: int, name: str) -> Response:
    """Sets the name of an item in the data store and returns the updated JSON, or 404 if not found."""
    if not name:
        return Response("Name cannot be empty\n", status=400, mimetype='text/plain')

    data_store = get_data_store()
    item = next((item for item in data_store if item['id'] == item_id), None)

    if item:
        item['name'] = name
        with DATA_STORE_LOCK:
            # Replace the old item with the updated one, preserving order
            new_data_store = [updated_item if updated_item['id'] == item['id'] else old_item
                              for updated_item, old_item in zip([item], data_store)]
            DATA_STORE[:] = new_data_store
        return jsonify(item)
    else:
        abort(404)


@app.route('/getset/<int:item_id>/<done>', methods=['GET'])
def set_item_done(item_id: int, done: str) -> Response:
    """Sets the 'done' status of an item in the data store and returns the updated JSON, or 404 if not found."""
    try:
        done_value = (done.lower() == 'true')
    except AttributeError:
        return Response("Invalid 'done' value\n", status=400, mimetype='text/plain')

    data_store = get_data_store()
    item = next((item for item in data_store if item['id'] == item_id), None)

    if item:
        item['done'] = done_value
        with DATA_STORE_LOCK:
            # Replace the old item with the updated one, preserving order
            new_data_store = [updated_item if updated_item['id'] == item['id'] else old_item
                              for updated_item, old_item in zip([item], data_store)]
            DATA_STORE[:] = new_data_store
        return jsonify(item)
    else:
        abort(404)


@app.route('/add', methods=['POST'])
def add_item() -> Response:
    """Adds a new item to the data store and returns the new JSON, or 400 on error."""
    try:
        request_data = request.get_json()
        if not request_data or 'name' not in request_data:
            return Response("Name must be specified\n", status=400, mimetype='text/plain')
        name = request_data['name']

        if not name:
            return Response("Name cannot be empty\n", status=400, mimetype='text/plain')

        new_item = {
            'id': get_next_id(),
            'name': name,
            'done': False
        }

        with DATA_STORE_LOCK:
            DATA_STORE.append(new_item)

        return jsonify(new_item), 201

    except Exception as e:
        logging.error(f"Error adding item: {e}")
        return Response(f"Error adding item: {e}\n", status=502, mimetype='text/plain')


if __name__ == '__main__':
    def signal_handler(sig, frame):
        logging.info('You pressed Ctrl+C!')
        if serial_connection.is_available():
            serial_connection.close()
        exit(0)

    import signal
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    app.run(debug=False, host='0.0.0.0', port=5000)

