import json
import time
import logging
from threading import Thread
from typing import List, Dict, Any

import serial
from flask import Flask, Response, request, jsonify, abort

app = Flask(__name__)

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
DEFAULT_SERIAL_PORT = '/dev/ttyUSB0'
DEFAULT_BAUDRATE = 9600
DEFAULT_TIMEOUT = 1
MEMORY_SLOTS = 2

class SerialCommunicator:
    """
    Manages serial communication with the SCPI device.
    """
    def __init__(self, port: str = DEFAULT_SERIAL_PORT, baudrate: int = DEFAULT_BAUDRATE, timeout: int = DEFAULT_TIMEOUT):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None

    def open(self) -> bool:
        """Opens the serial port."""
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Serial port {self.port} opened successfully.")
            return True
        except serial.SerialException as e:
            logging.error(f"Error opening serial port {self.port}: {e}")
            return False

    def close(self) -> None:
        """Closes the serial port."""
        if self.serial and self.serial.is_open:
            self.serial.close()
            logging.info(f"Serial port {self.port} closed.")

    def send(self, message: str) -> str | None:
        """
        Sends a message to the serial port and returns the response.

        Args:
            message: The message to send.

        Returns:
            The response from the serial port, or None on error.
        """
        if not self.serial or not self.serial.is_open:
            logging.error("Serial port not open.")
            return None

        try:
            self.serial.write(message.encode())
            time.sleep(0.1)  # Adjust as needed
            response = self.serial.read_all().decode()
            return response
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"An unexpected error occurred: {e}")
            return None


class DataManager:
    """Manages the data stored in memory (simulated persistent storage)."""

    def __init__(self, slots: int = MEMORY_SLOTS):
        self.slots = slots
        self.data: List[Dict[str, Any]] = []
        self.lock = Thread  # Dummy lock for single-threaded operation

    def seed_data(self) -> None:
        """Seeds initial data."""
        self.data = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]

    def get_data(self) -> List[Dict[str, Any]]:
        """Returns all data."""
        with self.lock:  # Acquire lock (dummy)
            return self.data[:]  # Return a copy to prevent modification


    def get_item(self, item_id: int) -> Dict[str, Any] | None:
        """Returns an item by ID."""
        with self.lock:
            for item in self.data:
                if item['id'] == item_id:
                    return item.copy()  # Return a copy to prevent modification
            return None

    def add_item(self, item_name: str, item_done: bool = False) -> Dict[str, Any]:
        """Adds a new item."""
        with self.lock:
            next_id = (self.data[-1]['id'] + 1 if self.data else 1)
            new_item = {"id": next_id, "name": item_name, "done": item_done}
            self.data.append(new_item)
            return new_item.copy() # Return a copy



    def update_item(self, item_id: int, item_name: str | None = None, item_done: bool | None = None) -> Dict[str, Any] | None:
        """Updates an existing item."""
        with self.lock:
            item = self.get_item(item_id)
            if item:
                if item_name is not None:
                    item["name"] = item_name
                if item_done is not None:
                    item["done"] = item_done
                return item.copy() # Return a copy
            return None



class WebService:
    """Handles web requests."""

    def __init__(self, app: Flask, data_manager: DataManager, serial_communicator: SerialCommunicator):
        self.app = app
        self.data_manager = data_manager
        self.serial_communicator = serial_communicator

        self._register_routes()


    def _register_routes(self) -> None:
        """Registers Flask routes."""

        @self.app.route('/version', methods=['GET'])
        def get_version() -> str:
            """Retrieves the instrument version information."""
            if not self.serial_communicator.open():
                return "Serial port not available", 503

            try:
                response = self.serial_communicator.send("*IDN?\n")
                if response:
                    return response.replace('\n', '<br>')
                else:
                    return "No response from the instrument.", 504
            except Exception as e:
                logging.error(f"Error getting version: {e}")
                return f"Error: {e}", 500
            finally:
                self.serial_communicator.close()


        @self.app.route('/getdata', methods=['GET'])
        def get_data() -> Response:
            """Retrieves all data."""
            json_data = json.dumps(self.data_manager.get_data())
            return Response(json_data, mimetype='application/json')


        @self.app.route('/getset/<int:item_id>', methods=['GET'])
        def get_item(item_id: int) -> Response | Any:
            """Retrieves a single item by ID."""
            item = self.data_manager.get_item(item_id)
            if item:
                return Response(json.dumps(item), mimetype='application/json')
            else:
                abort(404)



        @self.app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
        def add_item(item_id: int, name: str) -> Response:
            """Adds a new item (simplified)."""

            new_item = self.data_manager.add_item(name, item_id > 0)
            json_data = json.dumps(self.data_manager.get_data())
            return Response(json_data, mimetype='application/json')


        @self.app.route('/postjson', methods=['POST'])
        def update_item_json() -> Response:
            """Updates an item via JSON data."""
            try:
                item_data = request.get_json()
                if not item_data:
                    abort(400, "No JSON data provided")

                item_id = item_data.get('id')
                item_name = item_data.get('name')
                item_done = item_data.get('done')


                if item_id is None:
                    abort(400, "Missing 'id' in JSON data")

                if self.data_manager.update_item(item_id, item_name, item_done):
                    json_data = json.dumps(self.data_manager.get_data())
                    return Response(json_data, mimetype='application/json')
                else:
                    abort(404, "Item not found")

            except KeyError as e:
                abort(400, f"Missing key in JSON data: {e}")
            except TypeError as e:
                abort(400, f"Invalid JSON data: {e}")


        @self.app.route('/postform', methods=['POST'])
        def update_item_form() -> Response:
            """Updates an item via form data."""
            try:
                item_id = int(request.form['id'])
                item_name = request.form.get('name')
                item_done = request.form.get('done') in ('True', 'true')

                if self.data_manager.update_item(item_id, item_name, item_done):
                    json_data = json.dumps(self.data_manager.get_data())
                    return Response(json_data, mimetype='application/json')
                else:
                    abort(404, "Item not found")

            except (KeyError, ValueError) as e:
                abort(400, f"Invalid form data: {e}")




if __name__ == '__main__':
    data_manager = DataManager()
    data_manager.seed_data()
    serial_communicator = SerialCommunicator()
    web_service = WebService(app, data_manager, serial_communicator)

    app.run(debug=True, host='0.0.0.0')

