import serial
import time
import subprocess

# Bluetooth serial port configuration
bluetooth_port = "/dev/rfcomm4"
bluetooth_baudrate = 38400
bluetooth_timeout = 1

def send_bluetooth_command(command_string):
    """Sends a command to the Bluetooth device."""
    try:
        print("Sending command:", command_string)
        bluetooth_connection.write(f"X{command_string}\n".encode())
        time.sleep(0.1)  # Allow time for the command to process
    except serial.SerialException as error:
        print("Error sending command:", error)

def establish_bluetooth_connection():
    """Establishes a Bluetooth serial connection."""
    global bluetooth_connection
    try:
        bluetooth_connection = serial.Serial(bluetooth_port, bluetooth_baudrate, timeout=bluetooth_timeout)
        print("Bluetooth connection established.")
    except serial.SerialException as error:
        print("Failed to connect to Bluetooth:", error)
        raise

def close_bluetooth_connection():
    """Closes the Bluetooth serial connection."""
    if 'bluetooth_connection' in locals() and bluetooth_connection.is_open:
        bluetooth_connection.close()
        print("Bluetooth connection closed.")

if __name__ == "__main__":
    try:
        establish_bluetooth_connection()
        while True:
            user_command = input("Enter command (or 'exit' to quit): ")
            if user_command.lower() == "exit":
                break
            send_bluetooth_command(user_command)
    except KeyboardInterrupt:
        print("\nExiting program.")
    except Exception as error:
        print("An unexpected error occurred:", error)
    finally:
        close_bluetooth_connection()

